 const doLogin=async(e)=>{e.preventDefault();if(!supabase)return notify('Add the Supabase URL and public anon key to .env.local first.');const {data:authData,error}=await supabase.auth.signInWithPassword({email,password});if(error)return notify(error.message);await refreshStore(authData.user.id);setPassword('');notify('Signed in securely')};
 const createOwner=async(e)=>{e.preventDefault();if(!supabase)return notify('Set up Supabase first.');const {data:authData,error}=await supabase.auth.signUp({email,password,options:{data:{name:form.ownerName||'Store owner'}}});if(error)return notify(error.message);if(!authData.session){return notify('Owner created. Turn off email confirmation in Supabase to finish first-time setup, then sign in.')}const {error:claimError}=await supabase.rpc('claim_first_owner');if(claimError){await supabase.auth.signOut();return notify('Owner setup failed: '+claimError.message)}setOwnerExists(true);await refreshStore(authData.user.id);setPassword('');notify('Owner account created')};
