 const updatePassword=async(e)=>{e.preventDefault();if(password.length<8)return notify('Use at least 8 characters.');const {error}=await supabase.auth.updateUser({password});if(error)return notify(error.message);setPassword('');setAuthMode('login');notify('Password changed. Please sign in.')};
 const addCategory=async()=>{if(role!=='owner')return notify('Only the owner can add categories.');const name=prompt('New category name');if(!name?.trim())return;const {error}=await supabase.from('categories').insert({name:name.trim()});if(error)return notify(error.message);setData(d=>({...d,categories:[...new Set([...(d.categories||[]),name.trim()])]}));notify('Category saved')};
 const createCategoryInline=async()=>{if(role!=='owner')return;const name=String(form.newCategory||'').trim();if(!name)return notify('Enter a category name.');if(categories.some(c=>c.toLowerCase()===name.toLowerCase())){updateForm('category',name);return notify('Category selected.')}if(supabase){const {error}=await supabase.from('categories').insert({name});if(error)return notify(error.message)}setData(d=>({...d,categories:[...new Set([...(d.categories||[]),name])]}));setForm(f=>({...f,category:name,newCategory:''}));notify('Category added')};
 const bulkSetCategoryLimit=async cat=>{if(role!=='owner')return notify('Only the owner can change stock limits.');const raw=prompt(`Set the low-stock limit for every ${cat} product:`,String(products.find(p=>p.category===cat)?.low_stock_limit??5));if(raw===null)return;const limit=Number(raw);if(!Number.isInteger(limit)||limit<0)return notify('Enter a whole number zero or greater.');if(supabase){const {error}=await supabase.from('products').update({low_stock_limit:limit}).eq('category',cat);if(error)return notify(error.message)}setData(d=>({...d,products:d.products.map(p=>p.category===cat?{...p,low_stock_limit:limit}:p)}));notify(`Low-stock limit ${limit} applied to ${cat}.`)};
