 if(!logged)return <div className="login-wrap"><div className="login-card"><div className="brand-mark"><Store size={30}/></div><div className="eyebrow">SATHVIKA M V · PROVISION STORE</div>{!supabase?<><h1>Connect your store database</h1><p className="muted">Add your Supabase project URL and public anon key to <code>.env.local</code>, then apply <code>supabase/schema.sql</code>.</p><div className="csv-columns"><b>Required setup</b><span>VITE_SUPABASE_URL<br/>VITE_SUPABASE_ANON_KEY</span></div></>:ownerExists===false?<><h1>Create owner account</h1><p className="muted">This one-time setup is available only while the store has no owner.</p><form onSubmit={createOwner}><label>Your name<input type="text" autoComplete="name" required value={form.ownerName||''} onChange={e=>updateForm('ownerName',e.target.value)} placeholder="Store owner"/></label><label>{t.email}<input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><label>{t.password}<input type="password" autoComplete="new-password" minLength="8" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/></label><button className="btn primary full" type="submit">Create owner account<ChevronRight size={19}/></button></form><p className="login-foot"><ShieldCheck size={15}/> Only the first account can become owner.</p></>:<><h1>{authMode==='forgot'?'Reset your password':authMode==='password-reset'?'Choose a new password':'Sign in to your store'}</h1><p className="muted">{authMode==='forgot'?'We will email you a secure reset link.':authMode==='password-reset'?'Choose a new password for your account.':'Your stock is shared securely with your team.'}</p><form onSubmit={authMode==='forgot'?e=>{e.preventDefault();forgotPassword()}:authMode==='password-reset'?updatePassword:doLogin}><label>{t.email}<input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label>{authMode!=='forgot'&&<label>{authMode==='password-reset'?'New password':t.password}<input type="password" autoComplete={authMode==='password-reset'?'new-password':'current-password'} required minLength="8" value={password} onChange={e=>setPassword(e.target.value)} placeholder={authMode==='password-reset'?'At least 8 characters':'Your password'}/></label>}<button className="btn primary full" type="submit">{authMode==='forgot'?'Send reset email':authMode==='password-reset'?'Save new password':t.continue}<ChevronRight size={19}/></button></form>{authMode==='forgot'||authMode==='password-reset'?<button className="text-action" onClick={()=>setAuthMode('login')}>Back to sign in</button>:<button className="text-action" onClick={()=>setAuthMode('forgot')}>Forgot password?</button>}{ownerExists===null&&<button className="text-action" onClick={()=>setOwnerExists(true)}>Already set up? Sign in</button>}</>}<div className="login-links">{supabase?'Secure Supabase authentication':'Setup needed'}<button onClick={()=>setLang(lang==='en'?'ta':'en')}><Languages size={15}/> {lang==='en'?'தமிழ்':'English'}</button></div></div></div>;
 const header=<header className="topbar"><div className="brand"><div className="brand-mark small"><Store size={20}/></div><div><b>Sathvika M V</b><small>Provision Store</small></div></div><div className="header-right">{offline&&<span className="offline-pill"><WifiOff size={14}/> Offline</span>}<button className="user-avatar" onClick={()=>{setTab('More');setScreen('')}}>{(displayName||email||'S').slice(0,1).toUpperCase()}</button></div></header>;
 const expiryTag=(date)=>{if(!date)return <span className="expiry amber">Check dates</span>;let days=daysTo(date);return <span className={`expiry ${days<0?'red':days<7?'red':days<45?'amber':'green'}`}>{days<0?`Expired ${Math.abs(days)}d`:days<45?`Expiring · ${days}d`:`${days} days left`}</span>};
 const productStatusTags=p=>{const bs=(p.batches||[]).filter(b=>b.units>0);const expired=bs.some(b=>b.expiry_date&&b.expiry_date<todayISO());const missing=bs.some(b=>!b.mfg_date||!b.expiry_date);const nearest=bs.filter(b=>b.expiry_date&&b.expiry_date>=todayISO()).sort((a,b)=>a.expiry_date.localeCompare(b.expiry_date))[0];return <div className="prod-expiry-tags">{expired&&<span className="expiry red">Expired</span>}{nearest&&expiryTag(nearest.expiry_date)}{missing&&<span className="expiry amber">Check dates</span>}</div>};
 const categoryPalette=['#dff1e5','#e9e4fb','#fff0d9','#dff1f4','#fde4e6','#e6ecd6'];const categoryColor=cat=>{let h=0;for(const c of String(cat||''))h=(h*31+c.charCodeAt(0))|0;return categoryPalette[Math.abs(h)%categoryPalette.length]};const productCard=p=><button className="product-card" key={p.id} onClick={()=>openProduct(p)}><div className="product-icon category-icon" style={{backgroundColor:categoryColor(p.category),color:'#244d39'}}>{(p.category||p.name||'?').trim().slice(0,1).toUpperCase()}</div><div className="prod-main"><strong>{p.name}</strong><span>{p.category} · {allUnits(p)} {p.unit_type==='piece'?'units':p.unit_type}</span>{productStatusTags(p)}</div><div className="prod-price"><b>{fmt(p.mrp)}</b><small>MRP</small></div><ChevronRight className="card-arrow" size={17}/></button>;
